# break와 continue
for i in range(10):
    if i == 3:
        continue  # 건너뛰기
    if i == 7:
        break     # 종료
    print(i)

# else 절 (break 없이 정상 종료 시 실행)
for i in range(5):
    print(i)
else:
    print("Loop completed")

# try-except
try:
    result = 10 / 0
except ZeroDivisionError:
    print("0으로 나눌 수 없습니다")

# 여러 예외 처리
try:
    value = int(input("숫자 입력: "))
    result = 100 / value
except ValueError:
    print("올바른 숫자가 아닙니다")
except ZeroDivisionError:
    print("0으로 나눌 수 없습니다")
except Exception as e:
    print(f"오류 발생: {e}")
else:
    print(f"결과: {result}")
finally:
    print("항상 실행됩니다")

# 예외 발생
def validate_age(age):
    if age < 0:
        raise ValueError("나이는 음수일 수 없습니다")
    return age

# 사용자 정의 예외
class CustomError(Exception):
    pass

try:
    raise CustomError("사용자 정의 오류")
except CustomError as e:
    print(e)
